arguments.command:
set -eu
file=/tmp/root-crontab.lg4lfh.txt
if [ ! -f "$file" ]; then
  echo "Temporary crontab export not found: $file" >&2
  exit 1
fi
awk '
  /^[[:space:]]*($|#)/ { print; next }
  /^[[:space:]]*[A-Za-z_][A-Za-z0-9_]*[[:space:]]*=/ { print; next }
  /^[[:space:]]*@/ { next }
  NF >= 6 { next }
  { print }
' "$file" > "$file.tmp"
mv "$file.tmp" "$file"
echo "Removed scheduled command lines from: $file"
echo "Remaining lines: $(wc -l < "$file")"
